draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw stick figure
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // Draw thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20 * Math.sin(t), H/2 - 20 - 10 * Math.cos(t), 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 - 20);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t), H/2 - 20 - 10 * Math.cos(t));
  ctx.stroke();

  // Draw fire
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 + 100 + 10 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fillStyle = 'orange';
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 + 100 + 10 * Math.sin(t), 5, 0, 2 * Math.PI);
  ctx.fillStyle = 'yellow';
  ctx.fill();

  ctx.restore();
}
